coordination.obligations:
CREATE TABLE "obligations" ("execution_id" TEXT NOT NULL, "exact_target" TEXT NOT NULL CHECK (length(exact_target) BETWEEN 1 AND 256), "lifecycle" TEXT NOT NULL, "reason_code" TEXT CHECK (reason_code IS NULL OR length(reason_code) BETWEEN 1 AND 64), "created_at_ms" INTEGER NOT NULL CHECK (created_at_ms >= 0), "updated_at_ms" INTEGER NOT NULL CHECK (updated_at_ms >= created_at_ms), "revision" INTEGER NOT NULL CHECK (revision > 0), "state" TEXT GENERATED ALWAYS AS (json_extract(lifecycle, '$.kind')) STORED NOT NULL CHECK (state IN ('pending','publishing','deferred','published','silent','failed')), "receipt_message_id" TEXT GENERATED ALWAYS AS (json_extract(lifecycle, '$.message_id')) STORED CHECK (
        receipt_message_id IS NULL OR length(receipt_message_id) BETWEEN 1 AND 256
    ), "receipt_seq" INTEGER GENERATED ALWAYS AS (json_extract(lifecycle, '$.seq')) STORED CHECK (receipt_seq IS NULL OR receipt_seq > 0), "success_terminal" INTEGER GENERATED ALWAYS AS (CASE WHEN state IN ('published','silent') THEN 1 ELSE 0 END) STORED, "retryable" INTEGER GENERATED ALWAYS AS (CASE WHEN state IN ('pending','deferred') THEN 1 ELSE 0 END) STORED, "intent_settled" INTEGER GENERATED ALWAYS AS (CASE WHEN state IN ('publishing','published','failed') THEN 1 ELSE 0 END) STORED, "receipt_settled" INTEGER GENERATED ALWAYS AS (CASE WHEN state = 'published' THEN 1 ELSE 0 END) STORED, PRIMARY KEY ("execution_id", "exact_target"), UNIQUE ("execution_id", "exact_target", "success_terminal"), UNIQUE ("execution_id", "exact_target", "retryable"), UNIQUE ("execution_id", "exact_target", "intent_settled"), UNIQUE ("execution_id", "exact_target", "receipt_settled"), CHECK ((receipt_message_id IS NULL) = (receipt_seq IS NULL)), CHECK (
        (state = 'published' AND receipt_message_id IS NOT NULL)
        OR (state != 'published' AND receipt_message_id IS NULL)
    ), FOREIGN KEY ("execution_id") REFERENCES "executions" ("execution_id") ON DELETE RESTRICT) STRICT

